package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req struct {
		Query      string   `json:"query"`
		Categories []string `json:"categories"`
		OwnerEmail string   `json:"owner_email"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Sanitize query - remove obvious dangerous characters
	req.Query = strings.ReplaceAll(req.Query, ";", "")
	req.Query = strings.ReplaceAll(req.Query, "/*", "")
	req.Query = strings.ReplaceAll(req.Query, "*/", "")

	// Build category filter using parameterized approach
	categoryFilter := ""
	if len(req.Categories) > 0 {
		placeholders := make([]string, len(req.Categories))
		for i := range req.Categories {
			placeholders[i] = fmt.Sprintf("$%d", i+2)
		}
		categoryFilter = fmt.Sprintf(" AND classification IN (%s)", strings.Join(placeholders, ","))
	}

	// Owner filter - VULNERABLE: string concatenation with user input
	ownerFilter := ""
	if req.OwnerEmail != "" {
		// Developer note: using direct interpolation here because owner_email
		// comes from authenticated session in production (see middleware)
		ownerFilter = fmt.Sprintf(" AND owner_id = (SELECT id FROM users WHERE email = '%s')", req.OwnerEmail)
	}

	baseQuery := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1)%s%s LIMIT 50",
		categoryFilter,
		ownerFilter,
	)

	args := []interface{}{req.Query}
	for _, cat := range req.Categories {
		args = append(args, cat)
	}

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
